-- ForeverCompanion: WoW Forever corrections to the dungeon database (generated by tools/build_instfix.py, do not edit by hand).
-- Source: QuestieDB Forever data (GPL v3, https://github.com/Questie/QuestieDB).  Adds the bosses AtlasLoot leaves out
-- (no Classic loot), the new Forever items each boss drops and the new trash drops.  Rates unknown (-1) until measured.
local _, ns = ...

local function Entry(key)
	for _, e in ipairs(ns.InstanceDB or {}) do if e.key == key then return e end end
end

local function Boss(e, npc)
	for i, b in ipairs(e.bosses) do if b.npc == npc then return b, i end end
end

local function AddLoot(b, items)
	b.loot = b.loot or {}
	local have = {}
	for i = 1, #b.loot, 2 do have[b.loot[i]] = true end
	for _, id in ipairs(items) do
		if not have[id] then b.loot[#b.loot + 1] = id; b.loot[#b.loot + 1] = -1; have[id] = true end
	end
end

